const setClientBillingPeriodAlertPercent = `-- name: SetClientBillingPeriodAlertPercent :exec
UPDATE client_billing_period
SET last_alert_percent = $1, updated_at = now()
WHERE id = $2 AND last_alert_percent < $1
`

type SetClientBillingPeriodAlertPercentParams struct {
	Percent int32       `json:"percent"`
	ID      pgtype.UUID `json:"id"`
}

// Monotonic: never lowers the watermark, so a threshold alerts only once
// even when two confirms race.
func (q *Queries) SetClientBillingPeriodAlertPercent(ctx context.Context, arg SetClientBillingPeriodAlertPercentParams) error {
	_, err := q.db.Exec(ctx, setClientBillingPeriodAlertPercent, arg.Percent, arg.ID)
	return err
}

