const sumConfirmedChargesInPeriod = `-- name: SumConfirmedChargesInPeriod :one
SELECT COALESCE(SUM(price_rub), 0)::float8 AS total
FROM client_billing_charge
WHERE period_id = $1 AND status = 'confirmed'
`

func (q *Queries) SumConfirmedChargesInPeriod(ctx context.Context, periodID pgtype.UUID) (float64, error) {
	row := q.db.QueryRow(ctx, sumConfirmedChargesInPeriod, periodID)
	var total float64
	err := row.Scan(&total)
	return total, err
}

